class RateLimiter:
    def __init__(self, min_interval=1.0):
        self.min_interval = min_interval
        self.last_request_time = {}
        self.lock = threading.Lock()

    def wait_if_needed(self, key="default"):
        with self.lock:
            current_time = time.time()
            if key in self.last_request_time:
                elapsed = current_time - self.last_request_time[key]
                if elapsed < self.min_interval:
                    wait_time = self.min_interval - elapsed
                    time.sleep(wait_time)
            self.last_request_time[key] = time.time()


xai_rate_limiter = RateLimiter(min_interval=0.5)


def validate_api_key(key, service):
    if not key:
        logger.error(f"{service} API key is required but not configured.")
        raise ValueError(f"{service} API key is required but not configured.")
    return True


def retry_on_rate_limit(max_retries=10):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            last_error = None
            for attempt in range(max_retries):
                try:
                    return func(*args, **kwargs)
                except requests.exceptions.HTTPError as e:
                    last_error = e
                    if e.response is not None and e.response.status_code == 429 and attempt < max_retries - 1:
                        base_wait = min(2**attempt, 60)
                        wait_time = base_wait + random.uniform(0.0, 5.0)
                        logger.warning(
                            f"Rate limit hit for {func.__name__}, waiting {wait_time:.2f}s before retry {attempt + 1}/{max_retries}"
                        )
                        time.sleep(wait_time)
                        continue
                    elif e.response is not None and e.response.status_code == 429:
                        logger.error(f"Rate limit exceeded after {max_retries} retries for {func.__name__}")
                        raise
                    raise
                except requests.exceptions.RequestException as e:
                    last_error = e
                    if attempt < max_retries - 1:
                        wait_time = (2**attempt) + random.uniform(0.0, 1.0)
                        logger.warning(
                            f"Request error for {func.__name__}, waiting {wait_time:.2f}s before retry {attempt + 1}/{max_retries}"
                        )
                        time.sleep(wait_time)
                        continue
                    raise Exception(f"Max retries exceeded for {func.__name__}"
                                    ) from last_error
            raise Exception(
                f"Max retries exceeded for {func.__name__}") from last_error
        return wrapper
    return decorator


class CerebrasAgent:
    def __init__(self, model="gpt-oss-120b"):
        self.model = model
        try:
            from cerebras.cloud.sdk import Cerebras
            self.client = Cerebras(api_key=CEREBRAS_API_KEY)
        except ImportError:
            logger.error("Cerebras SDK not available, falling back to requests")
            self.client = None
            self.headers = {
                "Authorization": f"Bearer {CEREBRAS_API_KEY}",
                "Content-Type": "application/json"
            }

    @retry_on_rate_limit()
    def chat(self, messages, temperature=0.07, max_tokens=None, timeout=180):
        validate_api_key(CEREBRAS_API_KEY, "Cerebras")

        if self.client:
            stream = self.client.chat.completions.create(
                messages=messages,
                model=self.model,
                stream=False,
                max_completion_tokens=int(max_tokens if max_tokens is not None else 8000),
                temperature=float(temperature),
                top_p=0.03,
                reasoning_effort="low" if self.model == "gpt-oss-120b" else None
            )
            return {
                "choices": [{
                    "message": {
                        "content": stream.choices[0].message.content,
                        "role": "assistant"
                    }
                }]
            }
        else:
            url = f"{CEREBRAS_BASE_URL}/chat/completions"
            payload = {
                "model": self.model,
                "messages": messages,
                "temperature": float(temperature),
                "max_tokens": int(max_tokens if max_tokens is not None else 65000)
            }
            response = requests.post(url, headers=self.headers, json=payload, timeout=timeout)
            response.raise_for_status()
            return response.json()


