def retry_on_rate_limit(max_retries=10):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            last_error = None
            for attempt in range(max_retries):
                try:
                    return func(*args, **kwargs)
                except requests.exceptions.HTTPError as e:
                    last_error = e
                    if e.response is not None and e.response.status_code == 429 and attempt < max_retries - 1:
                        base_wait = min(2**attempt, 60)
                        wait_time = base_wait + random.uniform(0.0, 5.0)
                        logger.warning(
                            f"Rate limit hit for {func.__name__}, waiting {wait_time:.2f}s before retry {attempt + 1}/{max_retries}"
                        )
                        time.sleep(wait_time)
                        continue
                    elif e.response is not None and e.response.status_code == 429:
                        logger.error(f"Rate limit exceeded after {max_retries} retries for {func.__name__}")
                        raise
                    raise
                except requests.exceptions.RequestException as e:
                    last_error = e
                    if attempt < max_retries - 1:
                        wait_time = (2**attempt) + random.uniform(0.0, 1.0)
                        logger.warning(
                            f"Request error for {func.__name__}, waiting {wait_time:.2f}s before retry {attempt + 1}/{max_retries}"
                        )
                        time.sleep(wait_time)
                        continue
                    raise Exception(f"Max retries exceeded for {func.__name__}"
                                    ) from last_error
            raise Exception(
                f"Max retries exceeded for {func.__name__}") from last_error
        return wrapper
    return decorator


