class ExaResearchAgent:
    def __init__(self, use_kernel_browser=False):
        self.exa = exa_client
        if not self.exa:
            raise ValueError("Exa kliens nem inicializálható - hiányzó API kulcs vagy SDK")
        self.use_kernel_browser = use_kernel_browser and kernel_client is not None
        self.kernel_browser_session = None

    @retry_on_rate_limit()
    def search(self, query, num_results=100, search_type="auto", **kwargs):
        validate_api_key(EXA_API_KEY, "Exa")
        try:
            result = self.exa.search(
                query=query,
                num_results=min(int(num_results), EXA_NUM_RESULTS_MAX),
                type=search_type.lower() if search_type else "auto",
                contents=False,
                **kwargs
            )
            return {
                "results": [
                    {
                        "id": r.id,
                        "url": r.url,
                        "title": r.title,
                        "score": r.score,
                        "published_date": r.published_date,
                        "author": r.author,
                    }
                    for r in result.results
                ]
            }
        except Exception as e:
            logger.error(f"Exa search hiba: {str(e)}")
            raise

    @retry_on_rate_limit()
    def get_contents(self, ids, text=True, **kwargs):
        validate_api_key(EXA_API_KEY, "Exa")
        try:
            if isinstance(ids, str):
                ids = [ids]

            urls = [item_id for item_id in ids if item_id.startswith("http")]
            if not urls:
                return {"contents": {}}

            result = self.exa.get_contents(urls=urls, text=text, **kwargs)

            contents_dict = {}
            for r in result.results:
                content_data = {
                    "url": r.url,
                    "title": r.title,
                    "id": r.id,
                    "text": r.text if hasattr(r, 'text') and r.text else ""
                }
                contents_dict[r.id] = content_data

            return {"contents": contents_dict}
        except Exception as e:
            logger.error(f"Exa get_contents hiba: {str(e)}")
            raise


class SubAgent:
    """Autonóm subagent párhuzamos kutatáshoz - Agent-specifikus modellekkel"""

    def __init__(self, agent_id: str, specialty: str, agent_model: Any, exa: ExaResearchAgent):
        self.agent_id = agent_id
        self.specialty = specialty
        self.agent_model = agent_model
        self.exa = exa
        self.groq_kimi = GroqKimiAgent()
        self.sources_found = []
        self.content_gathered = []
        self.status = "initializing"
        self.progress = 0

    def research(self, task_description: str, max_sources: int = 500) -> Dict[str, Any]:
        """Végrehajtja a kutatási feladatot - Exa keresések, fix 100 result/keresés"""
        self.status = "planning_searches"
        self.progress = 10

        # Generáljunk keresési lekérdezéseket
        planning_prompt = f"""Feladat: {task_description}
Specialty: {self.specialty}

Generálj keresési lekérdezéseket ehhez a kutatási feladathoz. 
Készíts minél több (akár 15-20) változatos keresési lekérdezést, amelyek fedik le a témát.
Válaszolj JSON formátumban: {{"queries": ["lekérdezés1", "lekérdezés2", ...]}}"""

        try:
            plan_response = self.agent_model.chat(
                [{"role": "system", "content": f"Te {self.specialty} területén kutatsz. Generálj sokrétű keresési lekérdezéseket."},
                 {"role": "user", "content": planning_prompt}],
                temperature=0.2,
                max_tokens=4096
            )
            plan_data = self._extract_json(plan_response["choices"][0]["message"]["content"])
            search_queries = plan_data.get("queries", [task_description])[:20]
        except Exception as e:
            logger.error(f"Query planning error: {e}")
            search_queries = [task_description, f"{self.specialty}: {task_description}"]

        self.status = "searching"
        self.progress = 20

        all_results = []
        seen_urls = set()

        # Minden keresés FIX 100 result
        with concurrent.futures.ThreadPoolExecutor(max_workers=5) as executor:
            futures = [executor.submit(self._execute_search, q, num_results=100) for q in search_queries]
            for idx, future in enumerate(concurrent.futures.as_completed(futures)):
                try:
                    results = future.result()
                    for res in results:
                        if res["url"] not in seen_urls and len(all_results) < max_sources:
                            seen_urls.add(res["url"])
                            all_results.append(res)
                except Exception as e:
                    logger.error(f"SubAgent {self.agent_id} search error: {e}")

                self.progress = 20 + int(((idx + 1) / len(search_queries)) * 40)

        self.progress = 60

        self.sources_found = all_results
        self.status = "analyzing"
        self.progress = 70

        # Tartalom letöltése batch-enként
        batch_size = 50
        for i in range(0, len(all_results), batch_size):
            batch_ids = [r["id"] for r in all_results[i:i+batch_size] if "id" in r]
            try:
                contents = self.exa.get_contents(batch_ids, text=True)
                self.content_gathered.extend([c for c in contents.get("contents", {}).values()])
            except Exception as e:
                logger.error(f"SubAgent {self.agent_id} content error: {e}")

            self.progress = 70 + int((i / len(all_results)) * 20)

        # Groq Kimi fact-checking - tényalapú ellenőrzés
        if self.content_gathered:
            self.status = "fact_checking"
            self.progress = 90

            try:
                fact_check_prompt = f"""Specialty: {self.specialty}
Task: {task_description}

Az alábbi {len(self.content_gathered)} forrás alapján végezz tényalapú ellenőrzést:
- NE használj placeholder vagy mock adatokat
- NE találj ki információt
- Csak a források konkrét adatait használd
- Jelöld meg a bizonytalan információkat

Források alapján készíts rövid, tényszerű összefoglalót."""

                fact_check_messages = [
                    {"role": "system", "content": "Te egy precíz, tényalapú kutató vagy. TILOS hazudni, kitalálni vagy placeholder adatokat használni."},
                    {"role": "user", "content": fact_check_prompt}
                ]

                verification = self.groq_kimi.chat(fact_check_messages, temperature=0.05, max_tokens=8192)
                verification_content = verification["choices"][0]["message"]["content"]

                # Hozzáadjuk a verifikált összefoglalót
                self.content_gathered.append({
                    "title": f"[VERIFIED] {self.specialty} - Fact-checked Summary",
                    "text": verification_content,
                    "url": "internal://fact-check",
                    "verified": True
                })

                logger.info(f"SubAgent {self.agent_id} fact-checking completed")
            except Exception as e:
                logger.error(f"SubAgent {self.agent_id} fact-checking error: {e}")

            self.progress = 95

        self.status = "completed"
        self.progress = 100

        return {
            "agent_id": self.agent_id,
            "specialty": self.specialty,
            "sources_count": len(self.sources_found),
            "content_count": len(self.content_gathered),
            "sources": self.sources_found,
            "contents": self.content_gathered
        }

    def _execute_search(self, query: str, num_results: int = 100) -> List[Dict]:
        """Egy keresési lekérdezés végrehajtása"""
        try:
            result = self.exa.search(query, num_results=num_results, search_type="auto")
            return result.get("results", [])
        except Exception as e:
            logger.error(f"Search error for query '{query}': {e}")
            return []

    def _extract_json(self, text: str) -> Dict:
        """JSON kinyerése szövegből"""
        text = (text or "").strip()
        try:
            return json.loads(text)
        except json.JSONDecodeError:
            pass

        json_match = re.search(r"```json\s*(\{.*?\})\s*```", text, re.DOTALL)
        if json_match:
            try:
                return json.loads(json_match.group(1))
            except:
                pass

        brace_count = 0
        start = -1
        for i, ch in enumerate(text):
            if ch == "{":
                if brace_count == 0:
                    start = i
                brace_count += 1
            elif ch == "}":
                brace_count -= 1
                if brace_count == 0 and start != -1:
                    try:
                        return json.loads(text[start:i + 1])
                    except:
                        start = -1
        return {}


class AdvancedResearchOrchestrator:
    """Iteratív kutatási orchestrator
    Főagent: Grok-4-0709 - feladatkiosztás és tervezés
    Middle agent: Grok-4-fast-reasoning - szintézis
    Subagent-ek: Grok-4-fast, GPT-OSS-120B, Kimi K2, GLM-4.6 (kutatás Exa-val)
    Végső jelentés: GPT-OSS-120B több ciklusban
    """

    def __init__(self):
        self.main_grok = Grok4Agent()
        self.middle_grok = Grok4FastReasoningAgent()
        self.exa = ExaResearchAgent()
        self.kimi = GroqKimiAgent()
        self.glm = GLM4Agent()
        self.gpt_oss = CerebrasAgent(model="gpt-oss-120b")
        self.grok_fast = Grok4FastAgent()

    def execute_deep_research(self, task_id: str, user_query: str, options: Dict = None) -> Dict[str, Any]:
        """Iteratív kutatás - Grok-4-0709 főagent irányítja a folyamatot"""

        max_hours = options.get("max_hours", 12) if options else 12
        max_sources = options.get("max_sources", 10000) if options else 10000
        target_report_kb = options.get("target_report_kb", 500) if options else 500

        start_time = time.time()
        max_duration = max_hours * 3600

        try:
            # 1. Főagent (Grok-4-0709) kutatási tervet készít
            with research_lock:
                research_tasks[task_id]["status"] = "deep_planning"
                research_tasks[task_id]["progress"] = 5

            logger.info("Főagent (Grok-4-0709) master kutatási terv generálása...")
            master_plan = self._generate_master_plan(user_query, max_sources)

            with research_lock:
                research_tasks[task_id]["master_plan"] = master_plan
                research_tasks[task_id]["progress"] = 10

            specialties = master_plan.get("specialties", [
                "általános kutatás", "technikai elemzés", "történeti kontextus",
                "statisztikai adatok", "szakértői vélemények", "jövőbeli trendek",
                "kapcsolódó területek", "ellentétes nézetek", "esettanulmányok",
                "implementációs részletek", "piaci elemzés", "technológiai áttekintés"
            ])

            # Iteratív kutatási ciklus
            all_iterations_data = []
            iteration = 0

            while iteration < DEEP_RESEARCH_ITERATIONS:
                iteration += 1
                logger.info(f"=== ITERÁCIÓ {iteration}/{DEEP_RESEARCH_ITERATIONS} ===")

                # 2. Subagent-ek kutatást végeznek
                with research_lock:
                    research_tasks[task_id]["status"] = f"iteration_{iteration}_research"
                    research_tasks[task_id]["current_iteration"] = iteration

                num_subagents = min(len(specialties), 12)
                subagent_models = [self.grok_fast, self.gpt_oss, self.kimi, self.glm]

                subagents = []
                for i in range(num_subagents):
                    agent_id = f"subagent_{i+1}_iter{iteration}"
                    specialty = specialties[i % len(specialties)]
                    model = subagent_models[i % len(subagent_models)]
                    subagent = SubAgent(agent_id, specialty, model, self.exa)
                    subagents.append(subagent)

                sources_per_agent = max_sources // (num_subagents * DEEP_RESEARCH_ITERATIONS)
                agent_results = []

                with concurrent.futures.ThreadPoolExecutor(max_workers=num_subagents) as executor:
                    futures = {}
                    for idx, subagent in enumerate(subagents):
                        task_desc = master_plan.get("tasks", {}).get(subagent.specialty, user_query)
                        future = executor.submit(subagent.research, task_desc, sources_per_agent)
                        futures[future] = idx

                    for future in concurrent.futures.as_completed(futures):
                        try:
                            result = future.result()
                            agent_results.append(result)
                        except Exception as e:
                            logger.error(f"Subagent error: {e}")

                # 3. Middle agent (Grok-4-fast-reasoning) szintetizál
                with research_lock:
                    research_tasks[task_id]["status"] = f"iteration_{iteration}_synthesis"

                logger.info(f"Middle agent (Grok-4-fast-reasoning) szintézis - iteráció {iteration}...")
                synthesis = self._synthesize_with_middle_agent(user_query, agent_results)

                # 4. Főagent (Grok-4-0709) értékeli és következő feladatot oszt ki
                all_iterations_data.append({
                    "iteration": iteration,
                    "agent_results": agent_results,
                    "synthesis": synthesis
                })

                total_sources = sum(len(d["agent_results"]) for d in all_iterations_data)
                progress = 10 + int((iteration / DEEP_RESEARCH_ITERATIONS) * 80)

                with research_lock:
                    research_tasks[task_id]["progress"] = progress
                    research_tasks[task_id]["total_sources"] = total_sources

                # Időlimit ellenőrzés
                elapsed = time.time() - start_time
                if elapsed > max_duration:
                    logger.warning("Időlimit elérve, kutatás befejezése...")
                    break

            # 5. Végső jelentés GPT-OSS-120B többciklusú generálással
            with research_lock:
                research_tasks[task_id]["status"] = "finalizing"
                research_tasks[task_id]["progress"] = 90

            logger.info("GPT-OSS-120B többciklusú végső jelentés generálás...")
            final_report = self._generate_final_report_multi_cycle(
                user_query, all_iterations_data, master_plan, target_report_kb
            )

            final_size_kb = len(final_report.encode('utf-8')) / 1024
            elapsed_hours = (time.time() - start_time) / 3600
            total_sources = sum(
                sum(r["sources_count"] for r in d["agent_results"]) 
                for d in all_iterations_data
            )

            with research_lock:
                research_tasks[task_id]["status"] = "completed"
                research_tasks[task_id]["progress"] = 100
                research_tasks[task_id]["report"] = final_report
                research_tasks[task_id]["final_report_size_kb"] = final_size_kb
                research_tasks[task_id]["elapsed_hours"] = elapsed_hours

            return {
                "success": True,
                "total_sources": total_sources,
                "iterations": iteration,
                "report_size_kb": final_size_kb,
                "elapsed_hours": elapsed_hours,
                "report": final_report
            }

        except Exception as e:
            logger.error(f"Deep research error for task {task_id}: {str(e)}", exc_info=True)
            with research_lock:
                if task_id in research_tasks:
                    research_tasks[task_id]["status"] = "error"
                    research_tasks[task_id]["error"] = str(e)
            return {"success": False, "error": str(e)}

    def _generate_master_plan(self, query: str, max_sources: int) -> Dict:
        """Master kutatási terv generálása - Főagent Grok-4-0709 használatával"""
        system = """Te Grok-4-0709 vagy, a főagent. Készíts részletes, többrétegű kutatási tervet.
        Határozd meg:
        1. A fő kutatási területeket (specialties) - legalább 10-12 különböző terület
        2. Mindegyik területhez specifikus kutatási feladatokat
        3. A kutatás fókuszpontjait
        4. Az elvárható eredményeket

        TILOS mock, placeholder vagy kitalált adatokat használni.
        Válaszolj tisztán JSON formátumban, semmi más szöveg."""

        user = f"""Kutatási téma: {query}

        Maximális források száma: {max_sources}

        Készíts átfogó kutatási tervet JSON formátumban:
        {{
          "specialties": ["terület1", "terület2", ...],
          "tasks": {{"terület1": "kutatási feladat leírása", ...}},
          "focus_points": ["fókusz1", "fókusz2", ...],
          "expected_outcomes": ["eredmény1", "eredmény2", ...]
        }}"""

        response = self.main_grok.chat(
            [{"role": "system", "content": system}, {"role": "user", "content": user}],
            temperature=0.3,
            max_tokens=256000
        )

        return self._extract_json(response["choices"][0]["message"]["content"])

    def _synthesize_with_middle_agent(self, query: str, agent_results: List[Dict]) -> str:
        """Middle agent (Grok-4-fast-reasoning) szintetizálja a subagent jelentéseket"""

        synthesis_text = f"# Kutatási téma: {query}\n\n## Subagent eredmények:\n\n"

        for result in agent_results:
            specialty = result["specialty"]
            sources_count = result.get("sources_count", 0)
            contents = result.get("contents", [])[:100]

            synthesis_text += f"### {specialty} (Források: {sources_count})\n\n"

            for c in contents[:20]:
                synthesis_text += f"- {c.get('title', 'N/A')}: {c.get('text', '')[:500]}...\n"

            synthesis_text += "\n"

        system = """Te Grok-4-fast-reasoning vagy, a middle agent. 
        Szintetizálj átfogó összefoglalót a subagent-ek jelentéseiből.
        TILOS mock, placeholder vagy kitalált adatokat használni.
        Csak a valós forrásokból származó információkat használd."""

        user = f"""Szintetizálj részletes összefoglalót az alábbi kutatási eredményekből:

{synthesis_text[:30000]}

Készíts strukturált, markdown formátumú összefoglalót."""

        try:
            response = self.middle_grok.chat(
                [{"role": "system", "content": system}, {"role": "user", "content": user}],
                temperature=0.3,
                max_tokens=2000000
            )
            return response["choices"][0]["message"]["content"]
        except Exception as e:
            logger.error(f"Middle agent synthesis error: {e}")
            return ""

    def _merge_reports(self, current_report: str, new_sections: List[str], query: str) -> str:
        """Jelentések összefűzése és bővítése"""
        if not current_report:
            # Első iteráció
            merged = f"# Átfogó Kutatási Jelentés: {query}\n\n"
            merged += f"Generálva: {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}\n\n"
            merged += "---\n\n"
        else:
            merged = current_report + "\n\n---\n\n"

        for idx, section in enumerate(new_sections, 1):
            merged += f"\n## Szakmai Terület {idx}\n\n{section}\n\n"

        return merged

    def _generate_final_report_multi_cycle(
        self, 
        query: str, 
        all_iterations_data: List[Dict], 
        master_plan: Dict,
        target_kb: int
    ) -> str:
        """Végső jelentés GPT-OSS-120B többciklusú generálással (8000 token max output)"""

        # Összes szintézis összegyűjtése
        all_synthesis = "\n\n---\n\n".join([
            f"# Iteráció {d['iteration']}\n\n{d['synthesis']}" 
            for d in all_iterations_data
        ])

        # Ciklusok száma a célméret eléréséhez
        target_bytes = target_kb * 1024
        estimated_cycles = max(1, int(target_bytes / (65000 * 4)))  # ~4 byte/token átlag, 65000 max output token

        logger.info(f"GPT-OSS végső jelentés generálás {estimated_cycles} ciklusban...")

        report_sections = []

        for cycle in range(1, estimated_cycles + 1):
            logger.info(f"GPT-OSS ciklus {cycle}/{estimated_cycles}")

            system = f"""Te GPT-OSS-120B vagy, a végső jelentés írója. 
            Ciklus {cycle}/{estimated_cycles} - Készíts részletes, szakmai jelentést.
            TILOS mock, placeholder vagy kitalált adatokat használni.
            Csak a valós kutatási eredményeket használd."""

            user = f"""Kutatási téma: {query}

Ciklus {cycle}/{estimated_cycles} - {'Bevezető és kontextus' if cycle == 1 else f'Részletes elemzés {cycle}. rész'}

Master terv:
{json.dumps(master_plan, indent=2, ensure_ascii=False)[:2000]}

Kutatási eredmények:
{all_synthesis[:25000]}

Írj részletes, strukturált jelentést markdown formátumban. 
Minimum 2000 szó, maximum részletességgel."""

            try:
                response = self.gpt_oss.chat(
                    [{"role": "system", "content": system}, {"role": "user", "content": user}],
                    temperature=0.5,
                    max_tokens=65000
                )
                section = response["choices"][0]["message"]["content"]
                report_sections.append(section)

                # Jelenlegi méret
                current_size = sum(len(s.encode('utf-8')) for s in report_sections)
                logger.info(f"Ciklus {cycle} kész, jelenlegi méret: {current_size / 1024:.1f} KB")

                if current_size >= target_bytes * 0.95:
                    logger.info("Célméret elérve, befejezés...")
                    break

            except Exception as e:
                logger.error(f"GPT-OSS ciklus {cycle} hiba: {e}")

        # Statisztikák és hivatkozások
        total_sources = sum(
            sum(r["sources_count"] for r in d["agent_results"]) 
